UPDATE article_index_outbox SET status=#{state},lease_until=NULL,last_error=#{error},
    available_at=TIMESTAMPADD(SECOND,#{seconds},UTC_TIMESTAMP(6))
    WHERE job_id=#{jobId} AND status='running' AND lease_token=#{token}

UPDATE article_index_outbox SET status='dispatched',lease_until=NULL,last_error=NULL,
    available_at=TIMESTAMPADD(SECOND,#{seconds},UTC_TIMESTAMP(6))
    WHERE job_id=#{jobId} AND status='running' AND lease_token=#{token}
